def fraction_from_continued(terms):
    num, den = terms[-1], 1
    for a in reversed(terms[:-1]):
        num, den = a * num + den, num
    if den < 0:
        num, den = -num, -den
    g = math.gcd(num, den)
    return (num // g, den // g)

def is_narcissistic_in_base(n, b):
    digits = []
    x = n
    if x == 0:
        digits = [0]
    while x > 0:
        digits.append(x % b)
        x //= b
    k = len(digits)
    return sum(d ** k for d in digits) == n

def sum_of_divisors_squared(n):
    total = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            total += i * i
            j = n // i
            if j != i:
                total += j * j
        i += 1
    return total

